  function weekCounts(id,sourcesOverride=null,overridesOverride=null){const key=whoKey(id),s=stateFor(id),counts=emptyCounts();let sword=0;for(let di=0;di<7;di++){const src=sourcesOverride?Number(sourcesOverride[di]):Number(s.daySources[di]||0);const d=clone(DATA[key][src].giorni[di]),ovs=overridesOverride?.[di]||s.overrides?.[di]||{};['Pranzo','Cena'].forEach(p=>{const donor=ovs[p]!=null?DATA[key][Number(ovs[p])].giorni[di]:d;const cat=donor.categorie[p];counts[cat]=(counts[cat]||0)+1;if(String(donor[p]).toLowerCase().includes('pesce spada'))sword++;});}return {counts,sword,exact:isExact(counts,key),distance:scoreDistance(counts,key)};}
