  function shuffled5(seed){const a=[0,1,2,3,4];for(let i=4;i>0;i--){const j=(seed+i*17)%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a;}
  function findBalancedSources(id){const key=whoKey(id),t=targetCounts(key),seed=(Date.now()>>>0)%9973,choice=new Array(7),counts=emptyCounts();function dfs(di,sword){if(di===7)return isExact(counts,key)&&sword<=1;const opts=shuffled5(seed+di*31);for(const wi of opts){const d=DATA[key][wi].giorni[di],v=dayVector(d),ns=sword+(d.pesceSpada?1:0);if(ns>1)continue;let ok=true;for(const k of Object.keys(t))if((counts[k]||0)+(v[k]||0)>t[k]){ok=false;break}if(!ok)continue;addVec(counts,v);choice[di]=wi;if(dfs(di+1,ns))return true;Object.keys(counts).forEach(k=>counts[k]-=(v[k]||0));}return false;}return dfs(0,0)?choice.slice():null;}
  window.usaSettimana120=function(id,wi){const key=whoKey(id);if(!key)return;const n=Math.max(0,Math.min(4,Number(wi)||0)),s=stateFor(id);s.daySources=[n,n,n,n,n,n,n];s.overrides={};s.mode='fonte';s.label=DATA[key][n].nome;syncPlan(id,true);renderSettimana();toast('Attiva: '+s.label);};
