  window.cambiaGiornoDieta120=function(id,di){const key=whoKey(id),s=stateFor(id),cur=Number(s.daySources[di]||0),before=weekCounts(id),candidates=[];for(let wi=0;wi<5;wi++){if(wi===cur)continue;const src=s.daySources.slice();src[di]=wi;const r=weekCounts(id,src,{});if(r.sword<=1)candidates.push({wi,r});}let pick=null;if(before.exact)pick=candidates.find(x=>x.r.exact);if(!pick)candidates.sort((a,b)=>a.r.distance-b.r.distance);pick=candidates.find(x=>x.r.distance<=before.distance)||candidates[0];if(!pick)return toast('Nessun altro giorno compatibile con i limiti settimanali');s.daySources[di]=pick.wi;if(s.overrides?.[di])delete s.overrides[di];s.mode='mix';s.label='Mix personalizzato';syncPlan(id,true);renderSettimana();toast(GIORNI[di]+' cambiato con '+DATA[key][pick.wi].nome);};
  function macroNear(a,b,key){const lim=key==='simona'?{kcal:45,P:5,C:9,G:4}:{kcal:110,P:7,C:14,G:6};return Math.abs(a.macro.kcal-b.macro.kcal)<=lim.kcal&&Math.abs(a.macro.P-b.macro.P)<=lim.P&&Math.abs(a.macro.C-b.macro.C)<=lim.C&&Math.abs(a.macro.G-b.macro.G)<=lim.G;}
  window.cambiaPastoDieta120=function(id,di,pasto){if(!['Pranzo','Cena'].includes(pasto))return;const key=whoKey(id),s=stateFor(id),cur=actualDay(id,di),currentText=cur[pasto],cat=cur.categorie[pasto],carb=cur.carb[pasto],baseSrc=Number(s.daySources[di]||0),base=DATA[key][baseSrc].giorni[di];const candidates=[];for(let wi=0;wi<5;wi++){const d=DATA[key][wi].giorni[di];if(d[pasto]===currentText)continue;if(d.categorie[pasto]!==cat||d.carb[pasto]!==carb)continue;if(!macroNear(base,d,key))continue;candidates.push(wi);}if(!candidates.length)return toast('Nessuno scambio equivalente disponibile per '+pasto.toLowerCase()+'. Prova “Cambia giorno”.');const ck=di+'|'+pasto,last=Number(s.mealCursor[ck]||-1),wi=candidates[(last+1)%candidates.length];s.mealCursor[ck]=(last+1)%candidates.length;s.overrides[di]=s.overrides[di]||{};s.overrides[di][pasto]=wi;s.mode='mix';s.label='Mix personalizzato';syncPlan(id,true);renderSettimana();toast(pasto+' cambiato con uno scambio equivalente');};
