  window.apriRegolePiano120=function(id){const key=whoKey(id);if(!key)return;const c=CFG[key];openModal('Regole e limiti · '+c.label,`<div class="note"><b>Obiettivi giornalieri del piano corretto</b><br>${c.target.kcal} kcal · P ${c.target.P} g · C ${c.target.C} g · G ${c.target.G} g.<br>Tolleranze pratiche: ${c.toll.kcal[0]}–${c.toll.kcal[1]} kcal; P ${c.toll.P[0]}–${c.toll.P[1]} g; C ${c.toll.C[0]}–${c.toll.C[1]} g; G ${c.toll.G[0]}–${c.toll.G[1]} g.</div><h3 style="margin-top:15px">Frequenze settimanali</h3><ul><li>Carne magra 3 volte, di cui carne rossa 1 (quindi carne bianca 2)</li><li>Pesce 4</li><li>Legumi 2</li><li>Uova 2</li><li>Affettati 1</li><li>Formaggio stagionato 2</li></ul><h3>Porzioni di riferimento</h3><ul>${c.porzioni.map(x=>'<li>'+H(x)+'</li>').join('')}</ul><h3>Note</h3><ul>${c.note.map(x=>'<li>'+H(x)+'</li>').join('')}</ul><div class="note">I cinque piani caricati restano consultabili come fonte. La funzione <b>Mischia settimana</b> seleziona giornate complete che rientrano già nelle tolleranze giornaliere e cerca una combinazione che rispetti anche le frequenze settimanali. “Cambia pranzo/cena” usa soltanto scambi equivalenti per categoria e presenza della quota di carboidrati.</div>`);};
